import {loadProjectBundle,rememberProjectBundle} from '@/lib/db';
import type {SourceEdit,WriteResult} from './host';

export type StandaloneNode={source:string;tag:string;props:Record<string,unknown>;parent?:string;text?:string};
export type StandaloneBundleModel={version:1;campaignId?:string;nodes:StandaloneNode[]};
const MARKER='/* BANNERMATIC_STANDALONE_MODEL:';

const encodeText=(value:string)=>{const bytes=new TextEncoder().encode(value);let out='';for(let i=0;i<bytes.length;i+=32768)out+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(out)};
const decodeText=(value:string)=>{const raw=atob(value),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return new TextDecoder().decode(bytes)};
const variable=(index:number)=>`bm_node_${index}`;

export function decodeStandaloneBundle(code:string):StandaloneBundleModel|null{const start=code.indexOf(MARKER);if(start<0)return null;const end=code.indexOf(' */',start);if(end<0)return null;try{return JSON.parse(decodeText(code.slice(start+MARKER.length,end))) as StandaloneBundleModel}catch{return null}}
export function encodeStandaloneBundle(model:StandaloneBundleModel){const sourceToVariable=new Map<string,string>(),lines:string[]=[];model.nodes.forEach((node,index)=>{const name=variable(index);sourceToVariable.set(node.source,name);lines.push(` const ${name}=createElement(${JSON.stringify(node.tag)}); spread(${name},${JSON.stringify({__source:node.source,...node.props})});`);if(node.text!==undefined)lines.push(` insertNode(${name},createTextNode(${JSON.stringify(node.text)}));`);if(node.parent)lines.push(` insertNode(${sourceToVariable.get(node.parent)||variable(0)},${name});`)});return`${MARKER}${encodeText(JSON.stringify(model))} */\nconst { createElement, createTextNode, spread, insertNode } = require("@diffusionstudio/jsx");\nfunction Project(){\n${lines.join('\n')}\n return ${variable(0)};\n}\nmodule.exports.default=Project;`}

const resolved=(value:string|undefined,ids:Record<string,string>)=>value?ids[value]||value:value;
export async function applyStandaloneEdits(projectId:string,edits:SourceEdit[]):Promise<WriteResult>{const current=await loadProjectBundle(projectId),model=current&&decodeStandaloneBundle(current);if(!model)return{skipped:[],error:'This browser project does not contain an editable standalone model.'};const ids:Record<string,string>={};for(const edit of edits){if(edit.kind==='insert'){const source=`bannermatic-edit:${crypto.randomUUID()}`;ids[edit.source]=source;const parent=resolved(edit.parent,ids);const node:StandaloneNode={source,tag:edit.tag,props:{...edit.props},...(parent?{parent}:{}),...(edit.text===undefined?{}:{text:edit.text})};const before=resolved(edit.before,ids),index=before?model.nodes.findIndex(item=>item.source===before):-1;model.nodes.splice(index>=0?index:model.nodes.length,0,node)}else if(edit.kind==='set'){const node=model.nodes.find(item=>item.source===resolved(edit.source,ids));if(node){node.props={...node.props,...edit.props};if(edit.text!==undefined)node.text=edit.text}}else if(edit.kind==='move'){const source=resolved(edit.source,ids),index=model.nodes.findIndex(item=>item.source===source);if(index>=0){const [node]=model.nodes.splice(index,1);node!.parent=resolved(edit.parent,ids);const before=resolved(edit.before,ids),target=before?model.nodes.findIndex(item=>item.source===before):-1;model.nodes.splice(target>=0?target:model.nodes.length,0,node!)}}else if(edit.kind==='remove'){const source=resolved(edit.source,ids),doomed=new Set([source]);let changed=true;while(changed){changed=false;for(const node of model.nodes)if(node.parent&&doomed.has(node.parent)&&!doomed.has(node.source)){doomed.add(node.source);changed=true}}model.nodes=model.nodes.filter(node=>!doomed.has(node.source))}}
 await rememberProjectBundle(projectId,encodeStandaloneBundle(model));return{skipped:[],ids,unrolled:[]}}
